import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] s = new long[n], e = new long[n];
        for (int i = 0; i < n; i++) { s[i] = sc.nextLong(); e[i] = sc.nextLong(); }
        Arrays.sort(s);
        Arrays.sort(e);
        int i = 0, j = 0, cur = 0, best = 0;
        while (i < n) {
            if (s[i] < e[j]) {
                cur++;
                best = Math.max(best, cur);
                i++;
            } else {
                cur--;
                j++;
            }
        }
        System.out.println(best);
    }
}

