import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        Map<Long, Long> freq = new HashMap<>();
        freq.put(0L, 1L);
        long prefix = 0, ans = 0;
        for (int i = 0; i < n; i++) {
            prefix += sc.nextLong();
            ans += freq.getOrDefault(prefix - k, 0L);
            freq.put(prefix, freq.getOrDefault(prefix, 0L) + 1L);
        }
        System.out.println(ans);
    }
}
